#include <set>
#include <algorithm>
#include <iostream>

int main() {
    std::set<int> coll2 = {1, 2, 3, 4, 5, 6};

    // 1. Range Erase: Removes {1, 2}
    auto end_of_range = coll2.find(3);
    coll2.erase(coll2.begin(), end_of_range);

    // 2. Key-Based Erase: Removes {5}
    int num_removed = coll2.erase(5);
    std::cout << num_removed << " element(s) removed by key.\n";

    // Remaining elements: 3 4 6
    for (int x : coll2) {
        std::cout << x << ' ';
    }
    std::cout << "\n";
}
